SELECT 'duplicate_customers' CHECK_NAME, COUNT(*)-COUNT(DISTINCT CUSTOMER_ID) FAILURES FROM CABLEBAHAMAS_DEMO.ANALYTICS.CUSTOMERS
UNION ALL SELECT 'cases_before_join',COUNT(*) FROM CABLEBAHAMAS_DEMO.ANALYTICS.SUPPORT_CASES S JOIN CABLEBAHAMAS_DEMO.ANALYTICS.CUSTOMERS C USING(CUSTOMER_ID) WHERE S.OPENED_DATE<C.JOIN_DATE
UNION ALL SELECT 'closure_before_creation',COUNT(*) FROM CABLEBAHAMAS_DEMO.ANALYTICS.B2B_PIPELINE WHERE CLOSE_DATE<CREATED_DATE
UNION ALL SELECT 'finance_identity',COUNT(*) FROM CABLEBAHAMAS_DEMO.ANALYTICS.MONTHLY_FINANCE WHERE EBITDA_BSD<>REVENUE_BSD-COST_OF_SERVICE_BSD-OPERATING_EXPENSE_BSD
UNION ALL SELECT 'invalid_coordinates',COUNT(*) FROM CABLEBAHAMAS_DEMO.ANALYTICS.NETWORK_DAILY WHERE LATITUDE NOT BETWEEN 20 AND 28 OR LONGITUDE NOT BETWEEN -80 AND -72
UNION ALL SELECT 'mobile_records',COUNT(*) FROM CABLEBAHAMAS_DEMO.ANALYTICS.PRODUCTS WHERE SERVICE_FAMILY ILIKE '%mobile%'
UNION ALL SELECT 'monthly_billing_mismatch',COUNT(*) FROM
(SELECT MONTH_START,SUM(REVENUE_BSD) REVENUE FROM CABLEBAHAMAS_DEMO.ANALYTICS.MONTHLY_FINANCE GROUP BY 1) F
JOIN (SELECT INVOICE_DATE,SUM(AMOUNT_BSD) BILLED FROM CABLEBAHAMAS_DEMO.ANALYTICS.INVOICES GROUP BY 1) I
ON F.MONTH_START=I.INVOICE_DATE WHERE F.REVENUE<>I.BILLED;
